@Composable internal fun ManagementDirectory(api:ApiClient,open:(String)->Unit){Column(verticalArrangement=Arrangement.spacedBy(12.dp)){
    if(api.can("manage_users"))TeacherMenu("Accounts","Identity, roles, phone numbers and activation"){open("manage/user")}
    if(api.can("manage_roles"))TeacherMenu("Roles & permissions","Manage capabilities and role metadata"){open("manage/role")}
    if(api.can("manage_rfid"))TeacherMenu("RFID registration","Connected scanner enrollment and assignment"){open("manage/rfid")}
    if(api.can("manage_academic_structure"))TeacherMenu("Academics","Departments, programs, subjects and offerings"){open("manage/academics")}
    if(api.can("manage_rooms"))TeacherMenu("Rooms & devices","Room details and connected scanner credentials"){open("manage/rooms")}
    if(api.can("manage_attendance_policies"))TeacherMenu("Attendance policies","Campus defaults and weekly schedule"){open("manage/policies")}
    if(api.can("manage_attendance_policies")&&api.can("manage_academic_calendar")){TeacherMenu("Academic calendar","School year, terms and departmental days off"){open("manage/calendar")}}
    if(api.can("manage_grading_settings"))TeacherMenu("Grading settings","Periods, weights and passing criteria"){open("manage/grading")}
    if(api.can("view_audit_logs"))TeacherMenu("Audit trail","Search records and inspect changes"){open("manage/audit")}
    if(api.can("manage_seat_plans"))TeacherMenu("Layout templates","Rooms and reusable seat-plan presets"){open("manage/seats")}
}}
@Composable internal fun ManagementHome(api:ApiClient,onExpired:()->Unit,open:(String)->Unit){LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(16.dp)){item{PageTitle("Campus workspace","Your permitted operations and campus insights.")};if(api.can("view_analytics")&&api.capabilities.optBoolean("campus_analytics"))item{TeacherMenu("Campus insights","Academic outcomes and attendance follow-ups"){open("analytics")}};item{RemotePanel(api,"workspace/dashboard.php?workspace=management",onExpired){json->val campus=json.optJSONObject("campus")?:JSONObject();Panel{Text("Campus snapshot",style=MaterialTheme.typography.titleLarge);listOf("students","teachers","staff","rfid_cards","rooms","upcoming_events","upcoming_recollections","deficient_students").filter{!campus.isNull(it)}.forEach{Text("${it.replace('_',' ').replaceFirstChar(Char::uppercase)}: ${campus.text(it)}")};json.optJSONObject("alerts")?.let{alerts->Text("${alerts.optJSONObject("summary")?.optInt("pending")?:0} attendance notices need review");TextButton(onClick={open("alerts")}){Text("Review attendance alerts")}}}}};item{ManagementDirectory(api,open)}}}

@Composable internal fun ManagementScreen(api:ApiClient,tool:String,onExpired:()->Unit,open:(String)->Unit){when(tool){
    "calendar"->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){item{TeacherMenu("School year & terms","Term boundaries and statuses"){open("manage/terms")}};item{TeacherMenu("Weekly schedules","Department regular days off"){open("manage/days-off")}}}
    "terms"->AcademicTerms(api,onExpired)
    "days-off"->DepartmentWeek(api,onExpired)
    else->if(tool.startsWith("enrollment/"))EnrollmentWorkspace(api,tool.substringAfter('/'),onExpired)else ManagementEntityRoute(api,tool,onExpired,open)
}}
@Composable private fun ManagementEntityRoute(api:ApiClient,tool:String,onExpired:()->Unit,open:(String)->Unit){when(tool){
    "academics"->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){item{PageTitle("Academics","Select a record group.")};items(listOf("department","program","course","section","offering")){type->TeacherMenu(type.replaceFirstChar(Char::uppercase),"Browse, create and edit records"){open("manage/$type")}}}
    "rooms"->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){item{PageTitle("Rooms & devices","Manage facilities and connected scanners.")};item{TeacherMenu("Rooms","Codes, buildings and room details"){open("manage/room")}};item{TeacherMenu("Devices","Assignments, status and credentials"){open("manage/device")}}}
    "users"->EntityManager(api,"user",onExpired,open)
    "audit-trail","audit"->AuditWorkspace(api,onExpired)
    "rfid"->RfidWorkspace(api,onExpired)
    "policies","grading"->PolicyWorkspace(api,tool,onExpired)
    "seats"->TeacherSeatPlans(api,onExpired,open)
    "compliance"->ComplianceManagement(api,onExpired)
    else->EntityManager(api,tool,onExpired,open)
}}

